/* ═════════ ١-٧ التقريبُ إلى أقربِ عشرةٍ ومئة ═════════ */
function roundTool(p0) { return el => {
  el.innerHTML = `<div class="row">العدد <input class="ans" data-kp="num" inputmode="none" style="width:110px" value="${AR(p0 === 3 ? 4684 : 62)}"> قرّبْ إلى <select class="rp">${['عشرة', 'مئة', 'ألف'].map((t, i) => `<option value="${i + 1}" ${i + 1 === p0 ? 'selected' : ''}>أقرب ${t}</option>`).join('')}</select> <button class="btn sm">قرّبْ</button></div><div class="rout"></div>`;
  const go = () => { const v = parseNum($('input', el).value), p = +$('.rp', el).value; if (isNaN(v) || v < 0) return; const s = String(Math.round(v)); const lo = Math.floor(v / 10 ** p) * 10 ** p, hi = lo + 10 ** p, r = roundTo(v, p);
    $('.rout', el).innerHTML = nlSVG(lo, hi, 10 ** p / (p === 1 ? 10 : p === 2 ? 10 : 2), [[v, AR(s), '#c8102e']], { lab: x => AR(x) }) + `<div class="keybox">${AR(s)} أقربُ إلى <b>${AR(r)}</b> منه إلى ${AR(r === lo ? hi : lo)}؛ إذن ${AR(s)} ≈ <b>${AR(r)}</b></div>`; };
  $('button', el).onclick = go; go(); }; }
