/* ═════════ هيّا بنا نلعب: تقريبُ الأعداد ═════════ */
function roundGame(el) {
  let score = [0, 0], round = 0;
  const next = (msg = '') => { if (round >= 8) { el.innerHTML = `<div class="keybox">${msg}<br><b>انتهتِ اللعبة: أنت ${AR(score[0])} – الحاسوب ${AR(score[1])} ${score[0] >= score[1] ? '🏆' : ''}</b></div><button class="btn">🔁 العبْ مجدّدًا</button>`; $('button', el).onclick = () => { score = [0, 0]; round = 0; next(); }; return; }
    round++; const n = rnd(1000, 9999), r = roundTo(n, 2), u = n % 10; const opts = shuf([...new Set([u, (u + rnd(1, 9)) % 10, (u + rnd(1, 9)) % 10, (u + 5) % 10])]).slice(0, 4); if (!opts.includes(u)) opts[0] = u;
    el.innerHTML = `<div class="meta">الجولة ${AR(round)} من ٨ · أنت ${AR(score[0])} – الحاسوب ${AR(score[1])}</div><div class="meta">${msg}</div><p>اختارَ الحاسوبُ عددًا من ٤ أرقام، وكتبَه مقرّبًا إلى أقربِ مئة: <b class="big">${AR(r)}</b></p><p>وهذه أرقامُه دونَ الآحاد: <b class="big">${AR(String(n).slice(0, 3))}■</b> — خمّنْ رقمَ الآحاد:</p><div class="row c">${shuf(opts).map(d => `<button class="btn" data-d="${d}" style="min-width:60px;font-size:22px">${AR(d)}</button>`).join('')}</div>`;
    $$('[data-d]', el).forEach(b => b.onclick = () => { const ok = +b.dataset.d === u; if (ok) { score[0]++; star(1); } else score[1]++; next(`${ok ? '✓ تخمينٌ صحيح!' : '✗ ليس كذلك.'} العددُ هو ${AR(n)}، ومقرّبًا إلى أقربِ مئة: ${AR(r)}`); });
  };
  next();
}
